import.meta.env = {"BASE_URL": "/", "DEV": true, "MODE": "development", "PROD": false, "SSR": false};/**
* 极简请求封装（V1 只用 React 本地 state + fetch，不引入任何状态管理库）。
*
* 业务接口自 TASK-001 起在此基础上扩展；业务数字一律以 EvidenceValue 传输，
* 前端不得自行计算业务数字（见 docs/DECISIONS.md D4）。
*/
const BASE_URL = import.meta.env.VITE_API_BASE_URL ?? "";
export async function apiGet(path) {
	const resp = await fetch(`${BASE_URL}${path}`, { headers: { Accept: "application/json" } });
	return parse(resp);
}
/** JSON 提交（沟通记录 / AI 回复）。后端失败时带 {"error": 错误码, "message": 说明}。 */
export async function apiPost(path, body) {
	const resp = await fetch(`${BASE_URL}${path}`, {
		method: "POST",
		headers: {
			"Content-Type": "application/json",
			Accept: "application/json"
		},
		body: JSON.stringify(body)
	});
	return parse(resp);
}
/** multipart 提交（导入预览/提交）。后端失败时带 {"error": 错误码, "message": 说明}。 */
export async function apiPostForm(path, form) {
	const resp = await fetch(`${BASE_URL}${path}`, {
		method: "POST",
		body: form
	});
	return parse(resp);
}
async function parse(resp) {
	const text = await resp.text();
	let payload = null;
	try {
		payload = text ? JSON.parse(text) : null;
	} catch {
		payload = null;
	}
	if (!resp.ok) {
		const body = payload ?? {};
		const message = body.message ?? body.detail ?? body.error ?? `请求失败：${resp.status}`;
		const err = {
			status: resp.status,
			message,
			code: body.error
		};
		throw err;
	}
	return payload;
}

